CREATE TABLE IF NOT EXISTS service_connectors(id INTEGER PRIMARY KEY AUTOINCREMENT,connector_key TEXT NOT NULL UNIQUE,label TEXT NOT NULL,service_type TEXT NOT NULL,base_url TEXT,auth_type TEXT NOT NULL DEFAULT 'none',capabilities_json TEXT NOT NULL DEFAULT '[]',ui_meta_json TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'disabled' CHECK(status IN('disabled','ready','degraded','error')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS service_connector_credentials(connector_id INTEGER PRIMARY KEY REFERENCES service_connectors(id) ON DELETE CASCADE,credentials_sealed TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS service_connector_health(connector_id INTEGER PRIMARY KEY REFERENCES service_connectors(id) ON DELETE CASCADE,last_ok_at TEXT,last_error_at TEXT,last_http_status INTEGER,last_error_code TEXT,last_error_message TEXT,latency_ms INTEGER,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS service_connector_idempotency(connector_id INTEGER NOT NULL REFERENCES service_connectors(id) ON DELETE CASCADE,idempotency_key TEXT NOT NULL,response_json TEXT NOT NULL DEFAULT '{}',expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(connector_id,idempotency_key));
CREATE TABLE IF NOT EXISTS service_connector_cache(connector_id INTEGER NOT NULL REFERENCES service_connectors(id) ON DELETE CASCADE,cache_key TEXT NOT NULL,payload_json TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(connector_id,cache_key));
CREATE INDEX IF NOT EXISTS idx_connector_health_status ON service_connector_health(last_ok_at,last_error_at);
